#!/usr/bin/env python3
"""Upgrade a project generated by agentbase-build-scaffold to the template of these skills.

    python3 upgrade.py <project-dir>            # dry run: print the plan, write nothing
    python3 upgrade.py <project-dir> --apply    # write it (the project's git worktree must be clean)

Per file, a 3-way merge: base = the template as it was generated for THIS project (same name / frontend, rendered by
the scaffold.sh of the recorded version), yours = the project's file, new = the template of these skills. You did not
change it ⇒ replaced; both changed ⇒ `git merge-file` (conflict markers left in the file and reported); new template
files are added; files the template dropped are reported and kept (--delete-removed deletes the ones you never
changed). Secrets and generated files are never read or written; seeds (README, system prompt, datasets,
mcp_servers.json…) are replaced only while untouched — the classes are defined in template_files.py.

Base: --from, else the scaffold_version recorded in .agentbase-template.json / .agentbase-state.json (…+git.<sha>),
rendered from the skills repo's history (this checkout, or --skills-repo when these skills are installed without
.git). Without history, the hashes in .agentbase-template.json still tell which files you never changed (replaced);
the ones you changed get the new template as <file>.agentbase-new to merge by hand.

  --from REF|VERSION|DIR  the skills that generated the project: a git ref of the skills repo, a version (0.3.0 =
                          the commit stamped with it that best matches the project) or a directory holding that
                          version's skills. Required before 0.3.0 (nothing recorded) — see --guess-from
  --guess-from            rank the skills commits by how many project files they generate byte-identical, then exit
  --to REF|DIR            upgrade to this version instead of the skills this script belongs to
  --skills-repo DIR       a git clone of the skills repo (history for skills installed without .git)
  --no-history            base = the manifest hashes only (no re-render from git)
  --apply                 write the plan (refused on a dirty or non-git project: the upgrade must be one diff)
  --allow-dirty           apply anyway (you lose the clean "upgrade = one diff" review)
  --delete-removed        delete files the template dropped when you never changed them
  --diff                  print the template's own change (old → new) of every file you need to look at
  --json                  print the plan as JSON

Exit: 0 = done / nothing to merge by hand, 1 = conflicts or manual merges remain (in a dry run: would remain),
2 = error or refused. Standard library only, Python >= 3.9; needs git and bash.
"""

from __future__ import annotations

import argparse
import difflib
import io
import json
import re
import shlex
import shutil
import subprocess
import sys
import tarfile
import tempfile
from dataclasses import dataclass
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import template_files as tf  # noqa: E402

SKILLS_DIR = Path(__file__).resolve().parents[2]
SCAFFOLD = "agentbase-build-scaffold/scripts/scaffold.sh"
REPO_URL = "https://github.com/greennode-samples/sample-greennode-agentbase-builder-skills.git"
LAST_PRE_030 = "3528ac6"  # last commit of the skills before 0.3.0 (projects without version info)
VERSION_RE = re.compile(r"^\d+\.\d+\.\d+$")
GIT_SHA_RE = re.compile(r"\+git\.([0-9a-f]{7,40})(\.dirty)?$")

# Reported actions, in report order (the quiet ones are only counted)
ACTIONS = {
    "conflict": "you and the template changed the same lines — conflict markers (<<<<<<<) left in the file",
    "manual": "no base to merge against — the new template is in <file>.agentbase-new: merge by hand, then delete it",
    "merge": "you and the template changed different lines — merged",
    "replace": "the template changed it, you did not — replaced",
    "add": "new in the template — added",
    "state": "standard/scaffold version updated, keys of the new template added (your values kept)",
    "skipped-owned": "yours (seed, developer_owned or not created by the scaffold) and the template changed it — kept;"
    " the new template is in <file>.agentbase-new for review",
    "removed-upstream": "no longer in the template — kept (delete it once nothing uses it)",
    "delete": "no longer in the template, never changed by you — deleted (--delete-removed)",
    "deleted-locally": "you deleted it and the template changed it since — not re-added",
}
QUIET = ("current", "unchanged")  # identical to the new template / the template did not change it
NEEDS_HAND = ("conflict", "manual")
NO_VERSION_HELP = f"""\
{{project}} records no standard_version / scaffold_version: it was scaffolded before 0.3.0. Name the skills
commit that generated it:
    python3 {{script}} {{project}} --guess-from     # ranks the skills commits by how many of your files they
                                                   # generate byte-identical
    python3 {{script}} {{project}} --from <commit>
If unsure, choose the OLDER candidate: a base older than the real one only adds conflicts, a newer one can silently
undo template fixes in files you changed. The last commit before 0.3.0 is {LAST_PRE_030}."""


class UpgradeError(Exception):
    """Stops the upgrade: exit 2 with this message."""


@dataclass
class Template:
    """A template rendered for the project: path → content (never-touch files, state and manifest excluded)."""

    label: str
    standard_version: str | None
    scaffold_version: str | None
    files: dict[str, bytes]
    modes: dict[str, int]
    state: bytes | None


@dataclass
class Item:
    path: str
    action: str
    owner: str
    note: str = ""
    write: bytes | None = None  # new content of the file
    sidecar: bytes | None = None  # written to <path>.agentbase-new
    mode: int | None = None  # file mode of an added file
    conflicts: int = 0
    adopted: bool = True  # listed in the new manifest (False: a file of yours the scaffold never created)
    diff: str = ""


# ---------------------------------------------------------------------------------------------------------- git


def git(*args: str, cwd: Path | None = None, check: bool = True) -> subprocess.CompletedProcess:
    proc = subprocess.run(["git", *args], cwd=cwd, capture_output=True)
    if check and proc.returncode != 0:
        raise UpgradeError(f"git {' '.join(args)}: {proc.stderr.decode(errors='replace').strip()}")
    return proc


def out(proc: subprocess.CompletedProcess) -> str:
    return proc.stdout.decode(errors="replace").strip()


def find_repo(explicit: str | None) -> Path | None:
    """The skills repo with history: --skills-repo, or the checkout these skills live in (as scaffold.sh decides)."""
    if shutil.which("git") is None:
        return None
    if explicit:
        repo = Path(explicit).expanduser().resolve()
        if (
            not (repo / "skills" / SCAFFOLD).is_file()
            or git("-C", str(repo), "rev-parse", "--git-dir", check=False).returncode
        ):
            raise UpgradeError(f"--skills-repo {explicit}: not a git clone of the skills repo (no skills/{SCAFFOLD})")
        return repo
    root = SKILLS_DIR.parent
    top = git("-C", str(root), "rev-parse", "--show-toplevel", check=False)
    if top.returncode == 0 and Path(out(top)).resolve() == root.resolve() and (root / "skills").resolve() == SKILLS_DIR:
        return root
    return None


def commit_of(repo: Path, ref: str) -> str | None:
    proc = git("-C", str(repo), "rev-parse", "--verify", "--quiet", f"{ref}^{{commit}}", check=False)
    return out(proc) if proc.returncode == 0 else None


def export_skills(repo: Path, sha: str, dest: Path) -> Path:
    """The skills/ directory of a commit, extracted to dest (git archive: no worktree, nothing written to the repo)."""
    proc = git("-C", str(repo), "archive", "--format=tar", sha, "skills")
    with tarfile.open(fileobj=io.BytesIO(proc.stdout)) as tar:
        if hasattr(tarfile, "data_filter"):
            tar.extractall(dest, filter="data")
        else:  # Python < 3.12 without the backport; the archive comes from the skills' own history
            tar.extractall(dest)  # noqa: S202
    return dest / "skills"


def skills_commits(repo: Path) -> list[str]:
    """Commits of HEAD that changed skills/, oldest first."""
    return out(git("-C", str(repo), "rev-list", "--reverse", "HEAD", "--", "skills")).split()


def stamped_version(repo: Path, sha: str) -> str | None:
    proc = git("-C", str(repo), "show", f"{sha}:skills/{SCAFFOLD}", check=False)
    m = re.search(r'^STANDARD_VERSION="([^"]+)"', proc.stdout.decode(errors="replace"), re.M)
    return m.group(1) if m else None


# ------------------------------------------------------------------------------------------------------- render


def render(skills: Path, name: str, frontend: bool, work: Path, sha: str | None = None) -> Template:
    """Run that version's own scaffold.sh (--no-sync) into a temporary dir; overlay the frontend template offline."""
    scaffold = skills / SCAFFOLD
    if not scaffold.is_file():
        raise UpgradeError(f"{skills}: no {SCAFFOLD} — not an agentbase-build skills directory")
    target = Path(tempfile.mkdtemp(prefix="render-", dir=work)) / "project"
    proc = subprocess.run(
        ["bash", str(scaffold), name, str(target), "--no-sync"], capture_output=True, stdin=subprocess.DEVNULL
    )
    if proc.returncode != 0:
        raise UpgradeError(
            f"rendering the template of {skills} failed (exit {proc.returncode}):\n"
            + proc.stderr.decode(errors="replace").strip()
        )
    files: dict[str, bytes] = {}
    modes: dict[str, int] = {}
    for path in sorted(target.rglob("*")):
        rel = path.relative_to(target).as_posix()
        if path.is_file() and not path.is_symlink() and rel not in (tf.STATE, tf.MANIFEST) and not tf.never_touch(rel):
            files[rel] = path.read_bytes()
            modes[rel] = path.stat().st_mode & 0o777
    if frontend:  # create-expo needs the network; only the overlay of agentbase-build-frontend is template
        for rel, data in tf.frontend_template(skills, name).items():
            files[rel], modes[rel] = data, 0o644
    state = (target / tf.STATE).read_bytes() if (target / tf.STATE).is_file() else None
    standard = scaffold_v = None
    if state:
        try:
            meta = json.loads(state)
            standard, scaffold_v = meta.get("standard_version"), meta.get("scaffold_version")
        except ValueError:
            pass
    if sha and standard and not GIT_SHA_RE.search(scaffold_v or ""):
        scaffold_v = f"{standard}+git.{sha[:7]}"  # exported from git: scaffold.sh could not see the SHA
    label = scaffold_v or (f"git {sha[:7]}" if sha else str(skills))
    return Template(label, standard, scaffold_v, files, modes, state)


def render_ref(repo: Path, sha: str, name: str, frontend: bool, work: Path) -> Template:
    dest = Path(tempfile.mkdtemp(prefix="skills-", dir=work))
    return render(export_skills(repo, sha, dest), name, frontend, work, sha)


def skills_in(path: Path) -> Path:
    """A directory given on the command line: the skills dir itself or a checkout / archive containing skills/."""
    return path / "skills" if (path / "skills" / SCAFFOLD).is_file() else path


def score(t: Template, project: Path, manifest: dict | None) -> tuple[int, int]:
    """How well a rendered template matches what generated the project: (matches, total)."""
    if manifest:  # exact: the hashes of what the scaffold wrote
        want = {rel: e["sha256"] for rel, e in manifest["files"].items() if e.get("sha256")}
        return sum(1 for rel, h in want.items() if rel in t.files and tf.sha256(t.files[rel]) == h), len(want)
    same = sum(1 for rel, data in t.files.items() if (project / rel).is_file() and (project / rel).read_bytes() == data)
    return same, len(t.files)


def best_match(
    repo: Path, shas: list[str], name: str, frontend: bool, project: Path, manifest: dict | None, work: Path
) -> tuple[Template, str]:
    """Render each candidate (oldest first); keep the best score — on a tie the OLDER commit (only adds conflicts)."""
    best: tuple[int, Template] | None = None
    results = []
    for sha in shas:
        t = render_ref(repo, sha, name, frontend, work)
        matches, total = score(t, project, manifest)
        results.append(f"{sha[:7]} {matches}/{total}")
        if best is None or matches > best[0]:
            best = (matches, t)
    assert best is not None
    return best[1], f"best match of {len(shas)} commits ({', '.join(results)})"


# --------------------------------------------------------------------------------------------------------- base


@dataclass
class Base:
    template: Template | None  # None: only the manifest's hashes
    how: str


def resolve_base(
    args: argparse.Namespace,
    project: Path,
    name: str,
    frontend: bool,
    manifest: dict | None,
    state: dict,
    repo: Path | None,
    work: Path,
    warnings: list[str],
) -> Base:
    recorded = (manifest or {}).get("scaffold_version") or state.get("scaffold_version")
    version = (manifest or {}).get("standard_version") or state.get("standard_version")
    no_repo = (
        f"these skills ({SKILLS_DIR}) have no git history — clone {REPO_URL} and pass --skills-repo <clone>,"
        " or --from <dir> with the old version's skills"
    )
    if args.from_:
        value = args.from_
        if Path(value).expanduser().is_dir():
            return Base(
                render(skills_in(Path(value).expanduser().resolve()), name, frontend, work), f"--from directory {value}"
            )
        if repo is None:
            raise UpgradeError(f"--from {value}: {no_repo}")
        if VERSION_RE.match(value) and not commit_of(repo, value):
            return version_base(value, repo, name, frontend, project, manifest, work, f"--from {value}")
        sha = commit_of(repo, value)
        if not sha:
            raise UpgradeError(f"--from {value}: no such commit in {repo} (git fetch? or a commit of {REPO_URL})")
        return Base(render_ref(repo, sha, name, frontend, work), f"--from {value} ({sha[:7]})")
    if args.no_history:
        if manifest is None:
            raise UpgradeError(f"--no-history needs {tf.MANIFEST} (written by scaffold.sh and by every upgrade)")
        return Base(None, f"hashes in {tf.MANIFEST} (--no-history)")
    if not recorded and not version:
        raise UpgradeError(NO_VERSION_HELP.format(project=project, script=Path(__file__).name))
    where = tf.MANIFEST if manifest else tf.STATE
    m = GIT_SHA_RE.search(recorded or "")
    problem = no_repo
    if m and repo:
        sha = commit_of(repo, m.group(1))
        if sha:
            if m.group(2):
                warnings.append(
                    f"scaffolded from a modified checkout ({recorded}): the base is commit {sha[:7]}"
                    " without those changes"
                    + (f"; files whose hash differs from {tf.MANIFEST} get" " <file>.agentbase-new" if manifest else "")
                )
            return Base(render_ref(repo, sha, name, frontend, work), f"{recorded} recorded in {where}")
        problem = f"commit {m.group(1)} is not in {repo} (git fetch, or --skills-repo <clone of {REPO_URL}>)"
    if version and repo:
        if m:
            warnings.append(f"{problem}: using the commits stamped {version} instead")
        return version_base(version, repo, name, frontend, project, manifest, work, f"{version} recorded in {where}")
    if manifest is not None:
        warnings.append(
            f"{problem}. Using the hashes in {tf.MANIFEST}: files you changed get <file>.agentbase-new"
            " instead of a 3-way merge"
        )
        return Base(None, f"hashes in {tf.MANIFEST} ({recorded})")
    raise UpgradeError(f"cannot rebuild the template {recorded or version} of {project}: {problem}")


def version_base(
    version: str, repo: Path, name: str, frontend: bool, project: Path, manifest: dict | None, work: Path, how: str
) -> Base:
    """Version without a SHA (skills installed without .git): the commit stamped with it that matches best."""
    shas = [sha for sha in skills_commits(repo) if stamped_version(repo, sha) == version]
    tag = commit_of(repo, f"v{version}")
    if tag and tag not in shas:
        shas.append(tag)
    if not shas:
        raise UpgradeError(f"no commit of {repo} is stamped STANDARD_VERSION={version} — pass --from <commit>")
    t, detail = best_match(repo, shas, name, frontend, project, manifest, work)
    return Base(t, f"{how}; {detail}")


# --------------------------------------------------------------------------------------------------------- plan


def is_binary(*blobs: bytes | None) -> bool:
    for b in blobs:
        if b is None:
            continue
        if b"\0" in b:
            return True
        try:
            b.decode("utf-8")
        except UnicodeDecodeError:
            return True
    return False


def merge3(yours: bytes, base: bytes, new: bytes, labels: tuple[str, str, str]) -> tuple[bytes, int]:
    with tempfile.TemporaryDirectory(prefix="merge-") as d:
        paths = []
        for i, data in enumerate((yours, base, new)):
            p = Path(d) / str(i)
            p.write_bytes(data)
            paths.append(str(p))
        proc = subprocess.run(
            ["git", "merge-file", "-p", "--diff3", "-L", labels[0], "-L", labels[1], "-L", labels[2], *paths],
            capture_output=True,
        )
    if not 0 <= proc.returncode <= 127:
        raise UpgradeError(f"git merge-file failed: {proc.stderr.decode(errors='replace').strip()}")
    return proc.stdout, proc.returncode


def template_diff(rel: str, old: bytes | None, new: bytes | None, old_label: str, new_label: str) -> str:
    if old is None and new is not None:
        return f"(no content for the old template of {rel} — compare with {rel}{tf.SIDECAR})\n"
    if is_binary(old, new):
        return f"(binary: {rel})\n"
    a = (old or b"").decode().splitlines(keepends=True)
    b = (new or b"").decode().splitlines(keepends=True)
    return "".join(difflib.unified_diff(a, b, f"{rel} (template {old_label})", f"{rel} (template {new_label})"))


def plan_file(
    rel: str,
    project: Path,
    base: Base,
    target: Template,
    manifest: dict | None,
    developer_owned: list[str],
    args: argparse.Namespace,
    mismatched: list[str],
) -> Item:
    n = target.files.get(rel)
    entry = (manifest or {}).get("files", {}).get(rel)
    b = base.template.files.get(rel) if base.template else None
    base_sha = entry.get("sha256") if entry else (tf.sha256(b) if b is not None else None)
    if entry and b is not None and tf.sha256(b) != base_sha:
        b = None  # the re-rendered base is not what the scaffold wrote here: trust the manifest hash only
        mismatched.append(rel)
    in_base = entry is not None or (base.template is not None and rel in base.template.files)
    path = project / rel
    p = path.read_bytes() if path.is_file() and not path.is_symlink() else None
    # A file the scaffold kept because it already existed (manifest lists only what it created) stays yours
    foreign = manifest is not None and entry is None and p is not None and (base.template is None or b is not None)
    cls = "seed" if foreign else tf.owner(rel, developer_owned)
    why = (
        "not created by the scaffold"
        if foreign
        else ("developer_owned" if cls == "seed" and tf.owner(rel) == "managed" else cls)
    )
    item = Item(rel, "unchanged", cls, adopted=not foreign)
    if path.is_symlink():
        item.action, item.note = "skipped-owned", "symlink — not followed"
        return item
    if n is None:  # dropped by the new template
        if p is None:
            item.action = "unchanged"
        elif base_sha and tf.sha256(p) == base_sha:
            item.action = "delete" if args.delete_removed else "removed-upstream"
            item.note = "" if item.action == "delete" else "unchanged since generated — safe to delete if unused"
        else:
            item.action, item.note = "removed-upstream", "you changed it"
        return item
    if p is None:
        if not in_base:
            item.action, item.write, item.mode = "add", n, target.modes.get(rel)
        elif base_sha != tf.sha256(n):
            item.action = "deleted-locally"
        return item
    if p == n:
        item.action, item.adopted = "current", True  # identical to the new template: the template's from now on
        return item
    if not in_base:  # a file of yours where the template now puts one
        item.action = "skipped-owned" if cls == "seed" else "manual"
        item.note, item.sidecar = f"{why}: your file is where the template now adds one", n
        return item
    if base_sha == tf.sha256(n):
        return item  # unchanged upstream: your version stays
    if tf.sha256(p) == base_sha:
        item.action, item.write = "replace", n
        return item
    if cls == "seed":
        item.action, item.note, item.sidecar = "skipped-owned", why, n
    elif b is None or is_binary(p, b, n):
        item.action, item.sidecar = "manual", n
        item.note = "binary" if b is not None else "the template it was generated from is not available"
    else:
        merged, conflicts = merge3(p, b, n, ("yours", f"template {base.template.label}", f"template {target.label}"))
        item.action, item.write, item.conflicts = ("conflict" if conflicts else "merge"), merged, conflicts
    if args.diff:
        item.diff = template_diff(rel, b, n, base.template.label if base.template else "?", target.label)
    return item


def add_missing(cur: dict, tpl: dict, added: list[str], prefix: str = "") -> dict:
    """cur + the keys of tpl it lacks (recursively), each inserted after its predecessor in tpl; values kept."""
    result = dict(cur)
    for key, value in tpl.items():
        if key not in result:
            added.append(prefix + key)
            items = list(result.items())
            before = [k for k in list(tpl)[: list(tpl).index(key)] if k in result]
            at = [k for k, _ in items].index(before[-1]) + 1 if before else 0
            items.insert(at, (key, value))
            result = dict(items)
        elif isinstance(value, dict) and isinstance(result[key], dict):
            result[key] = add_missing(result[key], value, added, f"{prefix}{key}.")
    return result


def plan_state(project: Path, target: Template) -> Item | None:
    if target.state is None:
        return None
    path = project / tf.STATE
    item = Item(tf.STATE, "current", "state")
    if not path.is_file():
        item.action, item.write = "add", target.state
        return item
    raw = path.read_bytes()
    try:
        cur = json.loads(raw)
        if not isinstance(cur, dict):
            raise ValueError("not an object")
    except ValueError as exc:
        item.action, item.sidecar, item.note = "manual", target.state, f"not valid JSON ({exc})"
        return item
    added: list[str] = []
    new = add_missing(cur, json.loads(target.state), added)
    new["standard_version"], new["scaffold_version"] = target.standard_version, target.scaffold_version
    text = (json.dumps(new, indent=2, ensure_ascii=False) + "\n").encode()
    if text != raw:
        item.action, item.write = "state", text
        item.note = f"{cur.get('scaffold_version') or 'no version'} → {target.scaffold_version}"
        if added:
            item.note += "; added " + ", ".join(added)
    return item


def makefile_alias(project: Path, manifest: dict | None) -> bool:
    """scaffold.sh wrote Makefile.agentbase next to an existing Makefile: the template Makefile maps to it."""
    return (project / "Makefile.agentbase").is_file() and (
        manifest is None or "Makefile.agentbase" in manifest["files"]
    )


def alias(t: Template | None) -> None:
    if t and "Makefile" in t.files:
        t.files["Makefile.agentbase"] = t.files.pop("Makefile")
        t.modes["Makefile.agentbase"] = t.modes.pop("Makefile")


# --------------------------------------------------------------------------------------------------------- main


def project_name(project: Path, manifest: dict | None, state: dict, explicit: str | None) -> str:
    name = explicit or (manifest or {}).get("project_name") or state.get("project_name")
    if not name:
        pyproject = project / "src/backend/pyproject.toml"
        m = (
            re.search(r'^name = "(.+)-backend"', pyproject.read_text(encoding="utf-8"), re.M)
            if pyproject.is_file()
            else None
        )
        name = m.group(1) if m else None
    if not name or not re.match(r"^[a-z][a-z0-9-]{1,38}[a-z0-9-]$", name):
        raise UpgradeError(f"cannot tell the project name of {project} (project_name in {tf.STATE}) — pass --name")
    return name


def dirty(project: Path) -> str | None:
    """Why the project cannot take an upgrade as one reviewable diff, or None."""
    if shutil.which("git") is None or git("-C", str(project), "rev-parse", "--show-toplevel", check=False).returncode:
        return "is not a git repository — `git init && git add -A && git commit` first, so the upgrade is one diff"
    status = out(git("-C", str(project), "status", "--porcelain", "--untracked-files=all", "--", "."))
    if status:
        lines = status.splitlines()
        return (
            f"has uncommitted changes ({len(lines)}: {', '.join(line[3:] for line in lines[:5])}"
            f"{', …' if len(lines) > 5 else ''}) — commit or stash them first, so the upgrade is one diff"
        )
    return None


def guess_from(
    args: argparse.Namespace,
    project: Path,
    name: str,
    frontend: bool,
    manifest: dict | None,
    repo: Path | None,
    work: Path,
) -> int:
    if repo is None:
        raise UpgradeError(f"--guess-from needs the skills' git history: clone {REPO_URL} and pass --skills-repo")
    rows = []
    for i, sha in enumerate(skills_commits(repo)):
        try:
            t = render_ref(repo, sha, name, frontend, work)
        except UpgradeError:
            continue  # too old to scaffold
        matches, total = score(t, project, manifest)
        info = out(git("-C", str(repo), "log", "-1", "--format=%h %cs %s", sha))
        rows.append((matches, -i, total, stamped_version(repo, sha) or "0.2.0", info))
    rows.sort(reverse=True)
    print(f"Skills commits ranked by the files of {project} they generate byte-identical:")
    for matches, _, total, version, info in rows[:10]:
        print(f"  {matches:4d}/{total:<4d} {version:8s} {info[:90]}")
    if rows:
        top = [r for r in rows if r[0] == rows[0][0]]
        pick = min(top, key=lambda r: -r[1])  # the oldest of the best
        print(
            f"\nSuggested: --from {pick[4].split()[0]}  (on a tie the OLDER commit: an older base only adds"
            " conflicts, a newer one can silently undo template fixes in files you changed)"
        )
    return 0


def report(
    items: list[Item],
    base: Base,
    target: Template,
    project: Path,
    name: str,
    frontend: bool,
    args: argparse.Namespace,
    warnings: list[str],
    code: int,
) -> None:
    by_action: dict[str, list[Item]] = {}
    for it in items:
        by_action.setdefault(it.action, []).append(it)
    if args.json:
        print(
            json.dumps(
                {
                    "dry_run": not args.apply,
                    "project": str(project),
                    "project_name": name,
                    "frontend": frontend,
                    "from": base.template.label if base.template else None,
                    "from_how": base.how,
                    "to": target.label,
                    "warnings": warnings,
                    "counts": {a: len(v) for a, v in by_action.items()},
                    "exit": code,
                    "items": [
                        {
                            "path": it.path,
                            "action": it.action,
                            "owner": it.owner,
                            "note": it.note,
                            "conflicts": it.conflicts,
                            **({"diff": it.diff} if args.diff else {}),
                        }
                        for it in items
                        if it.action not in QUIET
                    ],
                },
                indent=2,
                ensure_ascii=False,
            )
        )
        return
    mode = "APPLIED" if args.apply else "DRY RUN — nothing written"
    print(f"agentbase-build upgrade ({mode})")
    print(f"  project  {project}  ({name}, frontend: {'yes' if frontend else 'no'})")
    print(f"  from     {base.template.label if base.template else '(hashes only)'} — {base.how}")
    print(f"  to       {target.label}")
    for w in warnings:
        print(f"  ⚠ {w}")
    for action, meaning in ACTIONS.items():
        group = by_action.get(action, [])
        if not group:
            continue
        print(f"\n{action} ({len(group)}): {meaning}")
        for it in group:
            extra = f"{it.conflicts} conflict(s)" if it.conflicts else it.note
            print(f"    {it.path}{f'  — {extra}' if extra else ''}")
    print(
        f"\nuntouched: {len(by_action.get('unchanged', []))} files the template did not change,"
        f" {len(by_action.get('current', []))} already identical; secrets / generated files are never read"
    )
    if args.diff:
        for it in items:
            if it.diff:
                print(f"\n----- template change: {it.path}\n{it.diff}", end="")
    hand = sum(len(by_action.get(a, [])) for a in NEEDS_HAND)
    owned = len(by_action.get("skipped-owned", []))
    if all(it.action in QUIET for it in items):
        print("\nNothing to upgrade: the project already has every change of this template.")
        if args.apply and args.manifest_changed:
            print(f"Wrote {tf.MANIFEST} (ownership + template hashes for the next upgrade) — commit it.")
        return
    if not args.apply:
        cmd = ["python3", str(Path(__file__).resolve()), *args.argv, "--apply"]
        print(
            f"\n{hand} file(s) would need a manual merge. Review the plan (--diff shows the template's changes),"
            f" then: {' '.join(shlex.quote(c) for c in cmd)}"
        )
        return
    print("\nNext steps:")
    steps = []
    if hand:
        steps.append(
            f"Resolve the {hand} file(s) under conflict/manual (git diff; search '<<<<<<<'; merge each"
            " <file>.agentbase-new into <file>, then delete it)"
        )
    if owned:
        steps.append(
            f"Review the {owned} skipped-owned file(s): port what applies from <file>.agentbase-new, then delete it"
        )
    steps += [
        "cd src/backend && uv lock && uv sync      (never edit uv.lock by hand)",
        "make lint && make test",
        "make check-env ENV_FILE=src/backend/.env.<env>.example for each environment, and add any new keys to your"
        " git-ignored .env / .env.<env> copies (compare with the .example files)",
        "Read the skills CHANGELOG.md between the two versions (new settings, behavior changes), review `git diff`,"
        " commit the upgrade as one change",
    ]
    for i, step in enumerate(steps, 1):
        print(f"  {i}. {step}")


def main(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(
        usage="python3 upgrade.py <project-dir> [options]",
        description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    ap.add_argument("project")
    ap.add_argument("--from", dest="from_", metavar="REF|VERSION|DIR")
    ap.add_argument("--to", metavar="REF|DIR")
    ap.add_argument("--guess-from", action="store_true")
    ap.add_argument("--skills-repo", metavar="DIR")
    ap.add_argument("--no-history", action="store_true")
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("--allow-dirty", action="store_true")
    ap.add_argument("--delete-removed", action="store_true")
    ap.add_argument("--diff", action="store_true")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--name", help=argparse.SUPPRESS)
    args = ap.parse_args(argv)
    args.argv = argv

    project = Path(args.project).expanduser().resolve()
    if not (project / "src/backend").is_dir():
        raise UpgradeError(f"{project} has no src/backend — not a project generated by agentbase-build-scaffold")
    if shutil.which("git") is None or shutil.which("bash") is None:
        raise UpgradeError("git and bash are required")
    try:
        manifest = tf.load(project)
    except ValueError as exc:
        raise UpgradeError(str(exc)) from None
    try:
        state = json.loads((project / tf.STATE).read_text(encoding="utf-8")) if (project / tf.STATE).is_file() else {}
    except ValueError as exc:
        raise UpgradeError(f"{project / tf.STATE} is not valid JSON ({exc}) — fix it first") from None
    name = project_name(project, manifest, state, args.name)
    frontend = bool((manifest or {}).get("frontend")) or (project / tf.FRONTEND / "package.json").is_file()
    developer_owned = list((manifest or {}).get("developer_owned") or [])
    repo = find_repo(args.skills_repo)
    warnings: list[str] = []

    with tempfile.TemporaryDirectory(prefix="agentbase-upgrade-") as tmp:
        work = Path(tmp)
        if args.guess_from:
            return guess_from(args, project, name, frontend, manifest, repo, work)
        if args.to and Path(args.to).expanduser().is_dir():
            target = render(skills_in(Path(args.to).expanduser().resolve()), name, frontend, work)
        elif args.to:
            sha = commit_of(repo, args.to) if repo else None
            if not sha:
                raise UpgradeError(f"--to {args.to}: not a directory nor a commit of the skills repo")
            target = render_ref(repo, sha, name, frontend, work)
        else:
            target = render(SKILLS_DIR, name, frontend, work)
        base = resolve_base(args, project, name, frontend, manifest, state, repo, work, warnings)
        if makefile_alias(project, manifest):
            alias(base.template)
            alias(target)
        mismatched: list[str] = []
        paths = set(target.files) | set(base.template.files if base.template else ())
        paths |= {rel for rel, e in (manifest or {}).get("files", {}).items() if e.get("owner") != "state"}
        items = [
            plan_file(rel, project, base, target, manifest, developer_owned, args, mismatched)
            for rel in sorted(paths)
            if rel not in (tf.STATE, tf.MANIFEST) and not tf.never_touch(rel)
        ]
        state_item = plan_state(project, target)
        if state_item:
            items.append(state_item)
        if mismatched:
            warnings.append(
                f"{len(mismatched)} file(s) differ from what {tf.MANIFEST} says the scaffold wrote (e.g."
                f" {mismatched[0]}): not 3-way merged"
            )
        code = 1 if any(it.action in NEEDS_HAND for it in items) else 0

        args.manifest_changed = False
        if args.apply:
            reason = None if args.allow_dirty else dirty(project)
            if reason:
                raise UpgradeError(f"{project} {reason}. (--allow-dirty skips this check.)")
            for it in items:
                path = project / it.path
                if it.write is not None:
                    path.parent.mkdir(parents=True, exist_ok=True)
                    path.write_bytes(it.write)
                    if it.mode is not None and it.action == "add":
                        path.chmod(it.mode)
                if it.sidecar is not None:
                    Path(f"{path}{tf.SIDECAR}").write_bytes(it.sidecar)
                if it.action == "delete":
                    path.unlink()
            adopted = {it.path for it in items if it.adopted}
            files: dict[str, dict] = {
                rel: {"owner": tf.owner(rel, developer_owned), "sha256": tf.sha256(data)}
                for rel, data in target.files.items()
                if rel in adopted
            }
            if target.state is not None:
                files[tf.STATE] = {"owner": "state"}
            before = (project / tf.MANIFEST).read_bytes() if (project / tf.MANIFEST).is_file() else None
            tf.write(
                project,
                standard_version=target.standard_version,
                scaffold_version=target.scaffold_version,
                project_name=name,
                frontend=frontend,
                files=files,
                developer_owned=developer_owned,
            )
            args.manifest_changed = (project / tf.MANIFEST).read_bytes() != before
        report(items, base, target, project, name, frontend, args, warnings, code)
        return code


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except UpgradeError as exc:
        print(f"✖ {exc}", file=sys.stderr)
        sys.exit(2)
